theorem adjugate_augmentedJacobian_last_last {n : ℕ}
    (A : Matrix (Fin n) (Fin n) ℝ) (b : Fin n → ℝ) :
    (augmentedJacobian A b).adjugate (Fin.last n) (Fin.last n) = A.det
